Definition inr (lo n : Z) (x : word) : bool := (Z.leb lo (bv_unsigned x) && Z.ltb (bv_unsigned x) (lo + n))%bool.

Lemma inr_spec : forall lo n x, inr lo n x = true <-> (lo <= bv_unsigned x < lo + n)%Z.
Proof. ltac2:(KReplay.run [|constr:(@Corelib.Numbers.BinNums.Z); constr:(@stdpp.bitvector.definitions.bv); constr:(@Corelib.Numbers.BinNums.Npos); constr:(@Corelib.Numbers.BinNums.xO); constr:(@Corelib.Numbers.BinNums.xH); constr:(@Corelib.Init.Logic.iff); constr:(@Corelib.Init.Logic.eq); constr:(@Corelib.Init.Datatypes.bool); constr:(@Corelib.Init.Datatypes.andb); constr:(@Stdlib.ZArith.BinInt.Z.leb); constr:(@stdpp.bitvector.definitions.bv_unsigned); constr:(@Stdlib.ZArith.BinInt.Z.ltb); constr:(@Stdlib.ZArith.BinInt.Z.add); constr:(@Corelib.Init.Datatypes.true); constr:(@Corelib.Init.Logic.and); constr:(@Corelib.Classes.Morphisms.trans_co_eq_inv_impl_morphism); constr:(@Corelib.Classes.RelationClasses.iff_Transitive); constr:(@Stdlib.ZArith.BinInt.Z.le); constr:(@Stdlib.ZArith.BinInt.Z.lt); constr:(@Corelib.Classes.Morphisms.eq_proper_proxy); constr:(@Stdlib.Bool.Bool.andb_true_iff); constr:(@Corelib.Classes.Morphisms_Prop.and_iff_morphism); constr:(@Corelib.Classes.Morphisms.reflexive_proper_proxy); constr:(@Corelib.Classes.Morphisms.reflexive_reflexive_proxy); constr:(@Corelib.Classes.RelationClasses.iff_Reflexive); constr:(@Stdlib.ZArith.BinInt.Z.leb_le); constr:(@Corelib.Classes.Morphisms.Reflexive_partial_app_morphism); constr:(@Corelib.Classes.Morphisms.respectful); constr:(@Stdlib.ZArith.BinInt.Z.ltb_lt); constr:(@Corelib.Init.Logic.conj); constr:(@Corelib.Init.Logic.and_ind); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.As.AsStdioCall.inr)|] [|@lemma; @B; @H1; @H0; @H; @x; @n; @lo|] "##p#)#J#)#1###%#3#9#&#$#<#5#7#4#B#A#:#'#(#I#,#0#.#-#?#@#C#D#E#G#F#H#J#K#2#/#6#8#>#=#;,#C&#D$#1%#E%#F%#$%#G%#H%#I,$S&$#$#$#$#$#US'#US(#&$EVLF#'FJVM%#VN%##G#H#G'H#G&H%$#(&#&.JVLI#'IFVM%#VN%##G#H#G'H#G&H%$#*I+),*%$#VS)C#+CDK*'E$$#j#$1#VS*:8*F<(7#%+-WS+CDS,XOCD#/ZP1.E00#+CDK0&#--,j#$(#VS-Fs#$)s#%s##(?#k#%CCXS.CCDDXOCD,6_S/C%D$QP7#96E+CDK/6#665j#$(#VS0s#-s#+%4+k###:&s#2F'RI)$#&s#5I*S##'S#R)%#XS$%#JEj#&(#j#'s#&#YS1s#'s#&s#%#Ej#(/#XS$//##V32#V=<#Vs#'s#&#WS2FJE#G#H(#6m#&#j#)s#E#j#*S%#j#+S%##"). Qed.

Lemma inr_false : forall lo n x, inr lo n x = false <-> ~ (lo <= bv_unsigned x < lo + n)%Z.
Proof. intros lo n x. rewrite <- inr_spec. destruct (inr lo n x); split; congruence. Qed.

